) VALUES (
    'tour-de-ski-history',
    '{"en": "Tour de Ski: Cross-Country''s Ultimate Stage Race", "de": "Tour de Ski: Der ultimative Etappenrennen des Langlaufs", "fr": "Tour de Ski : La course à étapes ultime du ski de fond", "it": "Tour de Ski: La gara a tappe definitiva dello sci di fondo", "es": "Tour de Ski: La carrera por etapas definitiva del esquí de fondo", "pt": "Tour de Ski: A corrida de etapas definitiva do esqui cross-country", "nl": "Tour de Ski: De ultieme etappekoers van langlaufen", "ar": "جولة دي سكي: سباق المراحل النهائي للتزلج الريفي", "ja": "ツール・ド・スキー：クロスカントリーの究極のステージレース", "zh": "Tour de Ski: Yueye Huaxue de Zhongji Fenzhan Sai", "ko": "투르 드 스키: 크로스컨트리의 궁극적인 스테이지 레이스"}'::jsonb,
    '{"en": "The Tour de Ski brings the grand tour format to cross-country skiing. Multiple stages across Europe test endurance like no other event, culminating in the famous Alpe Cermis climb.", "de": "Die Tour de Ski bringt das Grand-Tour-Format zum Langlauf. Mehrere Etappen durch Europa testen die Ausdauer wie kein anderes Event.", "fr": "Le Tour de Ski apporte le format du grand tour au ski de fond. Plusieurs étapes à travers l''Europe testent l''endurance comme aucun autre événement.", "it": "Il Tour de Ski porta il formato del grande giro allo sci di fondo. Molteplici tappe in Europa testano la resistenza come nessun altro evento.", "es": "El Tour de Ski lleva el formato de gran vuelta al esquí de fondo. Múltiples etapas por Europa prueban la resistencia como ningún otro evento.", "pt": "O Tour de Ski traz o formato de grande volta ao esqui cross-country. Múltiplas etapas pela Europa testam a resistência como nenhum outro evento.", "nl": "De Tour de Ski brengt het grote ronde format naar langlaufen. Meerdere etappes door Europa testen uithoudingsvermogen als geen ander evenement.", "ar": "تجلب جولة دي سكي شكل الجولة الكبرى إلى التزلج الريفي. مراحل متعددة عبر أوروبا تختبر التحمل كما لا يفعل أي حدث آخر", "ja": "ツール・ド・スキーは、クロスカントリースキーにグランツール形式をもたらします。ヨーロッパ各地での複数のステージが、他に類を見ない持久力を試します。", "zh": "Tour de Ski jiang da huanjing saiche geshi dailai yueye huaxue. Hengkua Ouzhou de duo ge jieduan xiang meiyou qita saishi yiyang kaoyan naili.", "ko": "투르 드 스키는 크로스컨트리 스키에 그랜드 투어 형식을 도입합니다. 유럽 전역의 여러 스테이지가 다른 어떤 이벤트보다 지구력을 테스트합니다."}'::jsonb,
    '{"en": "<p>The Tour de Ski transformed <a href=\"/cross-country-skiing-guide/\">cross-country skiing</a> by introducing a multi-stage format inspired by cycling''s grand tours. Since its inception in 2006, this grueling competition has become one of the sport''s most anticipated events.</p><h2>The Concept</h2><p>The Tour de Ski takes place over approximately two weeks, typically starting in late December and finishing in early January. Athletes compete across multiple venues, facing different distances, techniques (classic and freestyle), and race formats.</p><p>Unlike traditional World Cup races where each event stands alone, the Tour de Ski accumulates results. Time bonuses and stage victories build toward the overall classification, creating strategic depth beyond simply skiing fast.</p><h2>The Iconic Finale</h2><p>The Tour de Ski culminates with a mass start final up the Alpe Cermis slope in <a href=\"/val-di-fiemme-venue-guide/\">Val di Fiemme</a>, Italy. This isn''t a typical ski course—it''s a steep alpine slope normally used for downhill skiing.</p><p>Athletes literally climb the mountain on skis, with the gradient testing every fiber of their exhausted bodies. The climb takes around 20 minutes and often determines the overall winner as tired legs battle the slope.</p><p>The finish line at the top offers one of cross-country skiing''s most dramatic conclusions.</p><h2>Great Champions</h2><p>Norway''s <a href=\"/therese-johaug-profile/\">Therese Johaug</a> and <a href=\"/johannes-klaebo-profile/\">Johannes Høsflot Klæbo</a> have dominated recent editions. Johaug''s endurance dominance made her nearly unbeatable on the final climb.</p><p>Swiss legend Dario Cologna won four times. Russian skier Alexander Legkov and Norwegian Marit Bjørgen have also claimed overall titles.</p><p><a href=\"/jessie-diggins-profile/\">Jessie Diggins</a> became the first American to win the overall title, a historic achievement for US skiing.</p><h2>Strategic Complexity</h2><p>The Tour de Ski rewards versatility. Athletes must perform well in sprints and distance races, in classic and freestyle technique. Time bonuses for stage wins add tactical considerations beyond simply minimizing time loss.</p><p>Some athletes skip the Tour to focus on specific World Cup races, while others target the overall victory as a season highlight.</p><h2>Venues and Stages</h2><p>The Tour typically visits venues in Germany, Switzerland, and Italy. Each venue offers different challenges—some favor sprinters, others reward pure endurance. The variety ensures no single skill set guarantees success.</p><h2>Legacy</h2><p>The Tour de Ski has established itself as cross-country skiing''s equivalent to cycling''s Tour de France—a multi-stage test of complete athletic ability. Its unique format and dramatic finale make it appointment viewing for skiing fans worldwide.</p>", "de": "<p>Die Tour de Ski hat den <a href=\"/cross-country-skiing-guide/\">Skilanglauf</a> transformiert, indem sie ein mehrstufiges Format nach dem Vorbild der großen Radsport-Rundfahrten einführte.</p><h2>Das Konzept</h2><p>Die Tour de Ski findet über etwa zwei Wochen statt, typischerweise von Ende Dezember bis Anfang Januar.</p><h2>Das ikonische Finale</h2><p>Die Tour de Ski gipfelt mit einem Massenstart-Finale den Alpe Cermis Hang in <a href=\"/val-di-fiemme-venue-guide/\">Val di Fiemme</a> hinauf.</p><h2>Große Champions</h2><p>Norwegens <a href=\"/therese-johaug-profile/\">Therese Johaug</a> und <a href=\"/johannes-klaebo-profile/\">Johannes Høsflot Klæbo</a> haben die letzten Ausgaben dominiert.</p>", "fr": "<p>Le Tour de Ski a transformé le <a href=\"/cross-country-skiing-guide/\">ski de fond</a> en introduisant un format à plusieurs étapes inspiré des grands tours cyclistes.</p><h2>Le concept</h2><p>Le Tour de Ski se déroule sur environ deux semaines, généralement de fin décembre à début janvier.</p><h2>La finale iconique</h2><p>Le Tour de Ski culmine avec une finale mass-start sur la pente de l''Alpe Cermis à <a href=\"/val-di-fiemme-venue-guide/\">Val di Fiemme</a>.</p><h2>Grands champions</h2><p><a href=\"/therese-johaug-profile/\">Therese Johaug</a> et <a href=\"/johannes-klaebo-profile/\">Johannes Høsflot Klæbo</a> de Norvège ont dominé les éditions récentes.</p>", "it": "<p>Il Tour de Ski ha trasformato lo <a href=\"/cross-country-skiing-guide/\">sci di fondo</a> introducendo un formato a più tappe ispirato ai grandi giri ciclistici.</p><h2>Il concetto</h2><p>Il Tour de Ski si svolge in circa due settimane, tipicamente da fine dicembre a inizio gennaio.</p><h2>La finale iconica</h2><p>Il Tour de Ski culmina con una finale mass start sulla salita dell''Alpe Cermis a <a href=\"/val-di-fiemme-venue-guide/\">Val di Fiemme</a>.</p><h2>Grandi campioni</h2><p><a href=\"/therese-johaug-profile/\">Therese Johaug</a> e <a href=\"/johannes-klaebo-profile/\">Johannes Høsflot Klæbo</a> della Norvegia hanno dominato le edizioni recenti.</p>", "es": "<p>El Tour de Ski transformó el <a href=\"/cross-country-skiing-guide/\">esquí de fondo</a> al introducir un formato de múltiples etapas inspirado en las grandes vueltas ciclistas.</p>", "pt": "<p>O Tour de Ski transformou o <a href=\"/cross-country-skiing-guide/\">esqui cross-country</a> ao introduzir um formato de múltiplas etapas inspirado nas grandes voltas ciclísticas.</p>", "nl": "<p>De Tour de Ski transformeerde <a href=\"/cross-country-skiing-guide/\">langlaufen</a> door een format met meerdere etappes te introduceren, geïnspireerd op grote wielerrondes.</p>", "ar": "<p>غيرت جولة دي سكي <a href=\"/cross-country-skiing-guide/\">التزلج الريفي</a> من خلال تقديم شكل متعدد المراحل مستوحى من جولات ركوب الدراجات الكبرى.</p>", "ja": "<p>ツール・ド・スキーは、サイクリングのグランツールにインスパイアされた複数ステージ形式を導入し、<a href=\"/cross-country-skiing-guide/\">クロスカントリースキー</a>を変革しました。</p>", "zh": "<p>Tour de Ski tongguoyinjin shou zixingche da huanjing saiche qifa de duo jieduan geshi, gaibian le <a href=\"/cross-country-skiing-guide/\">yueye huaxue</a>.</p>", "ko": "<p>투르 드 스키는 사이클링의 그랜드 투어에서 영감을 받은 다단계 형식을 도입하여 <a href=\"/cross-country-skiing-guide/\">크로스컨트리 스키</a>를 변화시켰습니다.</p>"}'::jsonb,
    'historical',
    'XC',
    '{"en": "Tour de Ski history - Cross-country skiing''s ultimate stage race culminating in the dramatic Alpe Cermis climb, established 2006.", "de": "Tour de Ski Geschichte - Das ultimative Etappenrennen des Langlaufs mit dem dramatischen Alpe Cermis Aufstieg.", "fr": "Histoire du Tour de Ski - La course à étapes ultime du ski de fond culminant avec l''ascension dramatique de l''Alpe Cermis.", "it": "Storia del Tour de Ski - La gara a tappe definitiva dello sci di fondo che culmina con la drammatica salita dell''Alpe Cermis.", "es": "Historia del Tour de Ski - La carrera por etapas definitiva del esquí de fondo que culmina con la dramática subida del Alpe Cermis.", "pt": "História do Tour de Ski - A corrida de etapas definitiva do esqui cross-country culminando na dramática subida do Alpe Cermis.", "nl": "Tour de Ski geschiedenis - De ultieme etappekoers van langlaufen met de dramatische Alpe Cermis klim.", "ar": "تاريخ جولة دي سكي - سباق المراحل النهائي للتزلج الريفي الذي يتوج بصعود ألب سيرميس الدرامي", "ja": "ツール・ド・スキーの歴史 - ドラマチックなアルペ・チェルミス登坂で最高潮に達するクロスカントリースキーの究極のステージレース", "zh": "Tour de Ski lishi - Yueye huaxue de zhongji fenzhan sai, yi xijuxing de Alpe Cermis pandeng wei gaochao", "ko": "투르 드 스키 역사 - 극적인 알페 체르미스 등반으로 최고조에 달하는 크로스컨트리 스키의 궁극적인 스테이지 레이스"}'::jsonb,
    'published',
    NOW(),
    'evergreen'
